def transform(grid):
    out=[r[:] for r in grid]
    # Repeated horizontal patterns: mark the trailing part that differs from
    # the corresponding earlier row-pattern, leaving matching background intact.
    h=len(grid); w=len(grid[0])
    bg=max(set(v for r in grid for v in r),key=lambda v:sum(r.count(v) for r in grid))
    # Identify duplicated row templates and mark differing tail cells in later copy.
    for i in range(h):
        for j in range(i+1,h):
            if j-i<3: continue
            a,b=grid[i],grid[j]
            # only compare a later row with a similar earlier row
            if sum(x==y for x,y in zip(a,b)) >= w//2:
                for c in range(w):
                    if a[c]!=b[c] and b[c]==bg and c>=max(0,w-8): out[j][c]=1
    return out

